def investigate(context, acquire):
    capacity = context['capacity']
    events = context['events']
    cache = {}
    lru_order = []
    hits = 0
    misses = 0
    for event in events:
        op = event['op']
        if op == 'reset':
            cache.clear()
            lru_order.clear()
            hits = 0
            misses = 0
        elif op == 'call':
            key = event['key']
            if key in cache:
                hits += 1
                lru_order.remove(key)
                lru_order.append(key)
            else:
                misses += 1
                if len(cache) >= capacity:
                    lru_key = lru_order[0]
                    cache.pop(lru_key)
                    lru_order.pop(0)
                cache[key] = True
                lru_order.append(key)
    size = len(cache)
    return {'hits': hits, 'misses': misses, 'size': size}

